using System; using System.Linq; using System.Collections.Generic; using Atm;
var cases = new (NoteCounts s, Denomination? j, int a)[] {
 (new(0,1,5),null,60),(new(5,5,5),null,180),(new(0,5,5),null,150),(new(0,5,0),null,100),(new(5,5,0),null,130),(new(1,0,5),null,100),(new(5,5,5),null,190),(new(0,4,1),null,90)};
