  var spy = new Spy(new MoneyDispenser(s,j));
  var r = new CashMachine(spy).Execute(new(250,0), new Operation.Withdraw(a));
  Console.WriteLine($"{s.Fifties}/{s.Twenties}/{s.Tens} {a}: {r.Status} -> " + string.Join(" | ", spy.Calls.Select(c=>$"({c.n.Fifties},{c.n.Twenties},{c.n.Tens})={c.ok}")));
}
class Spy(IMoneyDispenser i) : IMoneyDispenser {
  public List<(NoteCounts n,bool ok)> Calls = new();
  public NoteCounts Stock => i.Stock; public Denomination? Jammed => i.Jammed;
  public bool Dispense(NoteCounts n){ var ok=i.Dispense(n); Calls.Add((n,ok)); return ok; }
  public bool Load(NoteCounts n)=>i.Load(n);
}
